$root=__DIR__; $dataDir=$root.'/data'; $storeFile=$dataDir.'/store.json';
if(!is_dir($dataDir)) mkdir($dataDir,0775,true);
// Use a private, app-specific session directory to avoid broken system session.save_path settings.
$sessionDir=sys_get_temp_dir().'/drum_studio_sessions_'.substr(hash('sha256',$root),0,12);
if(!is_dir($sessionDir)) @mkdir($sessionDir,0700,true);
